# -*- coding: utf-8 -*-
"""Рядки 5503–5505: скільки правил рука 2 вимикає і чи картки рук 1 і 2 складаються з тих самих речей. 5 сцен стенда
(стенд_вх, каталог_повний) × сіди 1–5 — справжній `запити`; заглушка стенда (k-та річ слота, `рв6_стенд.js`) — 10 образів
руці: частка речей руки 2, що стоять тією самою річчю в образі руки 1, і «та сама сукня»; різниця пулів рук 1 і 2 (речей) по ярусу пари. На входах сіда 1 — 50 сідів жеребу: кількість поломок, правила, межа (різних аспектів серед кандидатів). Працює й на коді до 5503.
Запуск: cd джерела && python3 проби/рука2_поломок.py"""
import os, sys, json, re, collections
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); os.chdir(sys.path[0])
import bridge as B, правило_руки2 as ПР2
СЦ = {"office": dict(нагода="робота", місце="офіс", година=9, темп_c=18, дрес_код="business_casual"),
      "date": dict(нагода="побачення", місце="ресторан", година=20, темп_c=5, опади="дощ", тривалість_год=4),
      "wedding": dict(нагода="весілля_гість", місце="ресторан", година=16, темп_c=24, тривалість_год=8),
      "winter": dict(нагода="робота", місце="офіс", година=8, темп_c=-10, опади="сніг", тривалість_год=9),
      "park": dict(нагода="прогулянка", місце="парк", година=11, темп_c=15, тривалість_год=3)}
поле = lambda р, к: (re.search(к + r"=([^ ·]+)", р) or [None, ""])[1]
def образи(пул):   # заглушка стенда: образ i — сукня (непарний i) чи верх+низ, взуття, сумка, третя річ
    в = lambda с, i: (пул[с][i % len(пул[с])]["назва"], пул[с][i % len(пул[с])].get("ціна")) if пул.get(с) else None
    тр = [с for с in ("верхній_шар", "прикраси", "пояс", "шарф", "головний_убір", "сережки", "намисто") if пул.get(с)]
    return [[х for х in ([("сукня", в("сукня", i))] if пул.get("сукня") and i % 2 else [("верх", в("верх", i)), ("низ", в("низ", i))])
             + [("взуття", в("взуття", i)), ("сумка", в("сумка", i))] + ([(тр[i % len(тр)], в(тр[i % len(тр)], i))] if тр else []) if х[1]]
            for i in range(1, 11)]
вх0, сп, рч, сук, k, пр, межі, пд = json.load(open("стенд_вх.json")), 0, 0, [0, 0], collections.Counter(), collections.Counter(), collections.Counter(), {}
for ім, сц in СЦ.items():
    for сід in range(1, 6):
        з = json.loads(B.виклик("запити", json.dumps(dict(вх0, каталог="каталог_повний.xml", сід=сід, сценарій=сц), ensure_ascii=False)))
        for о1, о2 in zip(образи(з["пакети"]["1"]["пул"]), образи(з["пакети"]["2"]["пул"])):
            сп += len(set(о1) & set(о2)); рч += len(о2); д1, д2 = dict(о1).get("сукня"), dict(о2).get("сукня")
            if д1 and д2: сук[0] += 1; сук[1] += д1 == д2
        р = з["поломка"]["що_змінено"]; пд.setdefault(поле(р, "pair") == "pool", []).append(int(поле(р, "pool_diff") or 0)); print("%-8s сід %d → %s · pair=%s · pool_diff=%s" % (ім, сід, з["поломка"]["правило"], поле(р, "pair"), поле(р, "pool_diff")))
        if сід > 1: continue
        дост = set(поле(р, "with_input").split(",")); діє = {а.split(":")[0]: а.split(":")[1].split("+") for а in поле(р, "acts").split(",") if ":" in а}
        стар = ПР2.вхід; ПР2.вхід = lambda зп, d, п=None: (зп["ід"] in дост, None if зп["ід"] in дост else "x")
        дост -= getattr(ПР2, "ПОЗА_ЖЕРЕБОМ", set()); канд = sorted(і for і in дост if діє.get(і) or ПР2._лише_суд(і)) or sorted(дост)
        межі[getattr(ПР2, "межа_поломок", lambda і: 1)(канд)] += 1; print("   з входом %d · кандидатів %d · межа поломок %d" % (len(дост), len(канд), getattr(ПР2, "межа_поломок", lambda і: 1)(канд)))
        for с in range(50):
            зп = ПР2.жереб(dict(сід=с), None, діє=діє)[0]; k[зп.get("поломок", 1)] += 1; пр.update(зп.get("правила", (зп["ід"],)))
        ПР2.вхід = стар
print("поломок на 250 жеребах (5 сцен × 50 сідів):", dict(sorted(k.items())), "· середнє %.2f" % (sum(а * б for а, б in k.items()) / sum(k.values())))
print("межа поломок по сценах:", dict(sorted(межі.items())), "· правила:", dict(пр.most_common()))
print("заглушка, 5 сцен × 5 сідів × 10 образів: речей руки 2 тією самою річчю в образі руки 1 %d з %d (%.0f%%) · та сама сукня %d з %d" % (сп, рч, 100.0 * сп / max(1, рч), сук[1], сук[0]))
пп = пд.get(True, []); print("різниця пулів рук 1 і 2 (речей): pair=pool — %d прогонів, середнє %.0f, %s; інші пари — %s" % (len(пп), sum(пп) / max(1, len(пп)), sorted(пп), sorted(set(пд.get(False, [])))))
